/**
 * POSBarcode - Local Barcode Generator (Code 128B + UPC-A)
 * Generates barcodes as SVG. Fully offline, no dependencies.
 * 12-digit values are encoded as UPC-A (95 modules, ~1.75x wider bars than
 * Code128 for the same digits -> much easier for cameras to read) with a
 * correct GS1 check digit. Everything else falls back to Code 128B.
 */
(function (global) {
    'use strict';

    // Code 128 pattern table: each entry is 6 digits representing bar/space widths
    // Format: bar1,space1,bar2,space2,bar3,space3 (widths in modules)
    var PATTERNS = [
        '212222','222122','222221','121223','121322','131222','122213','122312','132212','221213',
        '221312','231212','112232','122132','122231','113222','123122','123221','223211','221132',
        '221231','213212','223112','312131','311222','321122','321221','312212','322112','322211',
        '212123','212321','232121','111323','131123','131321','112313','132113','132311','211313',
        '231113','231311','112133','112331','132131','113123','113321','133121','313121','211331',
        '231131','213113','213311','213131','311123','311321','331121','312113','312311','332111',
        '314111','221411','431111','111224','111422','121124','121421','141122','141221','112214',
        '112412','122114','122411','142112','142211','241211','221114','413111','241112','134111',
        '111242','121142','121241','114212','124112','124211','411212','421112','421211','212141',
        '214121','412121','111143','111341','131141','114113','114311','411113','411311','113141',
        '114131','311141','411131','211412','211214','211232','2331112'
    ];

    // Code B character values (ASCII 32-126 -> 0-94)
    function codeBValue(char) {
        return char.charCodeAt(0) - 32;
    }

    // UPC-A left (odd parity) and right (even parity) digit patterns, 7 modules each
    var UPC_L = ['0001101', '0011001', '0010011', '0111101', '0100011', '0110001', '0101111', '0111011', '0110111', '0001011'];
    var UPC_R = ['1110010', '1100110', '1101100', '1000010', '1011100', '1001110', '1010000', '1000100', '1001000', '1110100'];

    // GS1 UPC-A check digit for the first 11 digits
    function upcCheckDigit(first11) {
        var sum = 0;
        for (var i = 0; i < 11; i++) {
            var d = first11.charCodeAt(i) - 48;
            sum += (i % 2 === 0) ? d * 3 : d;
        }
        return String((10 - (sum % 10)) % 10);
    }

    // Encode a 12-digit UPC-A string into a 95-module bit string
    function upcBits(value) {
        var bits = '101'; // start guard
        var i;
        for (i = 0; i < 6; i++) bits += UPC_L[value.charCodeAt(i) - 48];
        bits += '01010'; // center guard
        for (i = 6; i < 12; i++) bits += UPC_R[value.charCodeAt(i) - 48];
        bits += '101'; // end guard
        return bits;
    }

    // Convert Code128 bar/space width array into a bit string
    function barsToBits(bars) {
        var bits = '';
        for (var i = 0; i < bars.length; i++) {
            var ch = (i % 2 === 0) ? '1' : '0';
            for (var j = 0; j < bars[i]; j++) bits += ch;
        }
        return bits;
    }

    /**
     * Resolve input text to an encodable barcode.
     * 12 digits -> UPC-A (with corrected check digit), anything else -> Code 128B.
     * @returns {{bits: string, display: string}|null} null when not encodable
     */
    function resolveBarcode(text) {
        var t = String(text === null || text === undefined ? '' : text).trim();
        if (/^\d{12}$/.test(t)) {
            var data11 = t.substring(0, 11);
            var value = data11 + upcCheckDigit(data11);
            return { bits: upcBits(value), display: value };
        }
        if (!t || !isValidCode128B(t)) return null;
        return { bits: barsToBits(valuesToBars(encode(t))), display: t };
    }

    function isValidCode128B(text) {
        for (var i = 0; i < text.length; i++) {
            var code = text.charCodeAt(i);
            if (code < 32 || code > 126) return false;
        }
        return true;
    }

    /**
     * Encode text as Code 128B, returns array of pattern indices
     */
    function encode(text) {
        var values = [];
        // Start Code B = 104
        values.push(104);

        for (var i = 0; i < text.length; i++) {
            values.push(codeBValue(text[i]));
        }

        // Calculate checksum
        var checksum = 104; // start code value
        for (var i = 0; i < text.length; i++) {
            checksum += codeBValue(text[i]) * (i + 1);
        }
        values.push(checksum % 103);

        // Stop code = 106
        values.push(106);

        return values;
    }

    /**
     * Convert encoded values to bar/space width array
     */
    function valuesToBars(values) {
        var bars = [];
        for (var i = 0; i < values.length; i++) {
            var pattern = PATTERNS[values[i]];
            if (!pattern) continue;
            for (var j = 0; j < pattern.length; j++) {
                bars.push(parseInt(pattern[j], 10));
            }
        }
        return bars;
    }

    /**
     * Generate SVG barcode
     * @param {string} text - barcode value (Code 128B compatible)
     * @param {object} options - {width, height, fontSize, margin, displayValue}
     * @returns {string} SVG markup
     */
    function generateSVG(text, options) {
        options = options || {};
        var moduleWidth = options.moduleWidth || 2;
        var barHeight = options.height || 50;
        var fontSize = options.fontSize || 12;
        var margin = options.margin || 10;
        var displayValue = options.displayValue !== false;
        var fontFamily = options.fontFamily || 'monospace';

        var resolved = resolveBarcode(text);
        if (!resolved) {
            // Fallback: render invalid indicator
            return '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="20">' +
                '<text x="5" y="15" font-size="12" fill="red">INVALID</text></svg>';
        }

        var bits = resolved.bits;

        var totalWidth = bits.length * moduleWidth + margin * 2;

        var textHeight = displayValue ? fontSize + 6 : 0;
        var totalHeight = barHeight + margin * 2 + textHeight;

        var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + totalWidth + '" height="' + totalHeight + '" viewBox="0 0 ' + totalWidth + ' ' + totalHeight + '">';

        // Background
        svg += '<rect width="' + totalWidth + '" height="' + totalHeight + '" fill="white"/>';

        // Draw bars (group consecutive runs of same color)
        var x = margin;
        var i = 0;
        while (i < bits.length) {
            var j = i;
            while (j < bits.length && bits[j] === bits[i]) j++;
            var w = (j - i) * moduleWidth;
            if (bits[i] === '1') {
                svg += '<rect x="' + x + '" y="' + margin + '" width="' + w + '" height="' + barHeight + '" fill="black"/>';
            }
            x += w;
            i = j;
        }

        // Draw text
        if (displayValue) {
            svg += '<text x="' + (totalWidth / 2) + '" y="' + (margin + barHeight + fontSize + 2) + '" ' +
                'font-size="' + fontSize + '" font-family="' + fontFamily + '" ' +
                'text-anchor="middle" fill="black">' + escapeXml(resolved.display) + '</text>';
        }

        svg += '</svg>';
        return svg;
    }

    /**
     * Render barcode into an element (replaces content)
     * @param {string|Element} element - CSS selector or DOM element
     * @param {string} text - barcode value
     * @param {object} options - see generateSVG
     */
    function render(element, text, options) {
        var el = typeof element === 'string' ? document.querySelector(element) : element;
        if (!el) return;
        el.innerHTML = generateSVG(text, options);
    }

    /**
     * Compute a module width that makes the barcode SVG fill the printable label width.
     * Bigger X-dimension = easier for cameras and scanners to read.
     * @param {string} text - barcode value
     * @param {string} labelWidth - e.g. '2in'
     * @param {number} margin - SVG margin in px (same used by generateSVG)
     * @param {number} fallback - module width to use when encoding fails
     * @returns {number}
     */
    function fitModuleWidth(text, labelWidth, margin, fallback) {
        var inches = parseFloat(labelWidth);
        if (!isFinite(inches) || inches <= 0) inches = 3;
        var resolved = resolveBarcode(text);
        if (!resolved || !resolved.bits.length) return fallback;
        var totalModules = resolved.bits.length;
        // Printable content width in CSS px (96px/in) minus @page margin, body padding and slack.
        var target = inches * 96 - 20;
        var mw = (target - margin * 2) / totalModules;
        if (!isFinite(mw) || mw < 0.7) mw = 0.7;
        if (mw > 4) mw = 4;
        return mw;
    }

    /**
     * Render barcode and trigger print of a label
     * @param {string} text - barcode value
     * @param {string} productName - product name to show on label
     * @param {string} price - optional price string
     * @param {object} options - {moduleWidth, height, showPrice, labelWidth, labelHeight}
     */
    function printLabel(text, productName, price, options) {
        options = options || {};
        var showPrice = options.showPrice !== false;
        var labelWidth = options.labelWidth || '2in';
        var labelHeight = options.labelHeight || '1.4in';
        var margin = 6;

        var svg = generateSVG(text, {
            moduleWidth: options.moduleWidth || fitModuleWidth(text, labelWidth, margin, 1.5),
            height: options.height || 50,
            fontSize: 10,
            margin: margin,
            displayValue: true
        });

        var html = '<!DOCTYPE html><html><head><title>Barcode Label</title><style>' +
            '@page { size: ' + labelWidth + ' ' + labelHeight + '; margin: 0.06in; }' +
            'body { margin: 0; padding: 0; font-family: Arial, sans-serif; text-align: center; }' +
            '.label { width: calc(' + labelWidth + ' - 0.12in); height: calc(' + labelHeight + ' - 0.12in); margin: 0 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; }' +
            '.product-name { font-size: 10px; font-weight: bold; margin-bottom: 2px; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }' +
            '.price { font-size: 11px; font-weight: bold; margin-top: 2px; }' +
            '.barcode svg { display: block; width: 100%; height: auto; }' +
            '</style></head><body>' +
            '<div class="label">' +
            (productName ? '<div class="product-name">' + escapeXml(productName) + '</div>' : '') +
            '<div class="barcode">' + svg + '</div>' +
            (showPrice && price ? '<div class="price">' + escapeXml(price) + '</div>' : '') +
            '</div>' +
            '</body></html>';

        var printWindow = window.open('', '_blank', 'width=300,height=200');
        if (!printWindow) {
            alert('Please allow popups to print barcode labels.');
            return;
        }
        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(function () {
            printWindow.print();
        }, 400);
    }

    /**
     * Print multiple barcode labels
     * @param {Array} items - [{barcode, productName, price, quantity}]
     * @param {object} options - {labelWidth, labelHeight, moduleWidth}
     */
    function printLabels(items, options) {
        options = options || {};
        var labelWidth = options.labelWidth || '2in';
        var labelHeight = options.labelHeight || '1.4in';
        var margin = 6;

        var labelsHtml = '';
        for (var i = 0; i < items.length; i++) {
            var item = items[i];
            var qty = item.quantity || 1;
            for (var q = 0; q < qty; q++) {
                var svg = generateSVG(item.barcode, {
                    moduleWidth: options.moduleWidth || fitModuleWidth(item.barcode, labelWidth, margin, 1.5),
                    height: options.height || 50,
                    fontSize: 10,
                    margin: margin,
                    displayValue: true
                });
                labelsHtml += '<div class="label">' +
                    (item.productName ? '<div class="product-name">' + escapeXml(item.productName) + '</div>' : '') +
                    '<div class="barcode">' + svg + '</div>' +
                    (item.price ? '<div class="price">' + escapeXml(item.price) + '</div>' : '') +
                    '</div>';
            }
        }

        var html = '<!DOCTYPE html><html><head><title>Barcode Labels</title><style>' +
            '@page { size: auto; margin: 0.25in; }' +
            'body { margin: 0; padding: 8px; font-family: Arial, sans-serif; }' +
            '.labels { display: flex; flex-wrap: wrap; gap: 6px; }' +
            '.label { width: ' + labelWidth + '; height: ' + labelHeight + '; display: flex; flex-direction: column; align-items: center; justify-content: center; page-break-inside: avoid; }' +
            '.product-name { font-size: 10px; font-weight: bold; margin-bottom: 2px; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }' +
            '.price { font-size: 11px; font-weight: bold; margin-top: 2px; }' +
            '.barcode svg { display: block; width: 100%; height: auto; }' +
            '</style></head><body>' +
            '<div class="labels">' + labelsHtml + '</div>' +
            '</body></html>';

        var printWindow = window.open('', '_blank', 'width=600,height=800');
        if (!printWindow) {
            alert('Please allow popups to print barcode labels.');
            return;
        }
        printWindow.document.write(html);
        printWindow.document.close();
        printWindow.focus();
        setTimeout(function () {
            printWindow.print();
        }, 400);
    }

    function escapeXml(str) {
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&apos;');
    }

    // Public API
    var POSBarcode = {
        generateSVG: generateSVG,
        render: render,
        printLabel: printLabel,
        printLabels: printLabels,
        isValid: isValidCode128B,
        encode: encode,
        resolve: resolveBarcode,
        upcCheckDigit: upcCheckDigit
    };

    // UMD export
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = POSBarcode;
    }
    if (typeof define === 'function' && define.amd) {
        define(function () { return POSBarcode; });
    }
    global.POSBarcode = POSBarcode;

})(typeof window !== 'undefined' ? window : this);
